var n=`1355-seco-de-chivo`;var t=`world-1355`;var o=`EC`;var a=`south-america`;var s=4;var r=179;var d={en:`Seco de Chivo`,ua:`Секо де чіво`};var g={en:`Seco de Chivo is a dish from Ecuador featuring goat shoulder, garlic, yellow onion, red bell pepper. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Секо де чіво, страва кухні країни Еквадор з такими основними складниками: козяча лопатка, часник, жовта цибуля, червоний солодкий перець. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var l=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 55 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 55 хвилин.`,t:[`marinating`],m:55,i:[[`goat-shoulder`,800,`g`],[`ground-cumin`,6,`g`],[`garlic`,5,`clove`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 11 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 11 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:11,i:[[`yellow-onion`,175,`g`],[`red-bell-pepper`,160,`g`],[`canola-oil`,40,`ml`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 110 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 110 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:110,i:[[`light-beer`,260,`ml`],[`beef-stock`,650,`ml`],[`tomato`,250,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,25,`g`]]}];var u={slug:n,id:t,country:`EC`,region:a,servings:4,minutes:179,title:d,text:g,steps:l};export{o as country,u as default,t as id,r as minutes,a as region,s as servings,n as slug,l as steps,g as text,d as title};